// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amountA, uint256 amountD) public {
        vm.assume(amountD > 0); // avoid division by zero and keep it positive for inequality
        vm.deal(address(this), 1 ether);
        c.OpenToThePublic();
        c.AdjustBetAmounts(amountA);
        c.AdjustDifficulty(amountD);
        uint256 diff = c.currentDifficulty();
        assertTrue(diff <= amountD);
    }
}

